110	union ScalarNum {
111	  uint64_t value_u64;
112	  int64_t value_i64;
113	  float value_f32;
114	  ScalarNum() : value_u64(0) {}
115	  explicit ScalarNum(uint64_t value) : value_u64(value) {}
116	  explicit ScalarNum(int64_t value) : value_i64(value) {}
117	  explicit ScalarNum(float value) : value_f32(value) {}
