122	struct ScalarVar {
123	  ScalarType scalar_type;
124	  ScalarNum scalar_num;
125	  ScalarVar() : scalar_type(ScalarType::INVALID_DTYPE) {}
126	  ScalarVar(ScalarType type, uint64_t num) : scalar_type(type), scalar_num(num) {
127	    if (type == ScalarType::FLOAT32 || type == ScalarType::FLOAT16) {
128	      scalar_num = ScalarNum(static_cast<float>(num));
129	    }
130	  }
131	  ScalarVar(ScalarType type, int64_t num) : scalar_type(type), scalar_num(num) {
132	    if (type == ScalarType::FLOAT32 || type == ScalarType::FLOAT16) {
133	      scalar_num = ScalarNum(static_cast<float>(num));
134	    }
135	  }
136	  ScalarVar(ScalarType type, int num) : scalar_type(type), scalar_num(static_cast<int64_t>(num)) {
137	    if (type == ScalarType::FLOAT32 || type == ScalarType::FLOAT16) {
138	      scalar_num = ScalarNum(static_cast<float>(num));
139	    }
140	  }
141	  ScalarVar(ScalarType type, unsigned int num) : scalar_type(type), scalar_num(static_cast<uint64_t>(num)) {
142	    if (type == ScalarType::FLOAT32 || type == ScalarType::FLOAT16) {
143	      scalar_num = ScalarNum(static_cast<float>(num));
144	    }
145	  }
146	  ScalarVar(ScalarType type, float num) : scalar_type(type), scalar_num(num) {
147	    if (type != ScalarType::FLOAT32 && type != ScalarType::FLOAT16) {
148	      if (type == ScalarType::UINT64) {
149	        scalar_num = ScalarNum(static_cast<uint64_t>(num));
150	      }
151	      scalar_num = ScalarNum(static_cast<int64_t>(num));
152	    }
153	  }
154	  ScalarVar(ScalarType type, double num) : scalar_type(type), scalar_num(static_cast<float>(num)) {
155	    if (type != ScalarType::FLOAT32 && type != ScalarType::FLOAT16) {
156	      if (type == ScalarType::UINT64) {
157	        scalar_num = ScalarNum(static_cast<uint64_t>(num));
158	      }
159	      scalar_num = ScalarNum(static_cast<int64_t>(num));
160	    }
161	  }
162	  bool operator==(const ScalarVar &other) const {
163	    if (scalar_type == other.scalar_type && scalar_num.value_u64 == other.scalar_num.value_u64) {
164	      return true;
165	    }
166	    return false;
167	  }
168	};
