151	uint32_t OpDefImpl::GetNonListLen(const OpDef *parent_this, std::vector<OpParamDef> &input_param,
152	                                  std::vector<OpParamDef> &output_param) const {
153	  std::unordered_set<uint32_t> non_list_lens;
154	  auto set_non_list_len = [parent_this, &non_list_lens](const std::vector<OpParamDef> &params) {
155	    for (auto &def : params) {
156	      if (parent_this->IsNonListTypes(def)) {
157	        non_list_lens.insert(def.impl_->types.size());
158	      }
159	      if (parent_this->IsNonListFormats(def)) {
160	        non_list_lens.insert(def.impl_->formats.size());
161	      }
162	    }
163	  };
164	  set_non_list_len(input_param);
165	  set_non_list_len(output_param);
166	
167	  if (non_list_lens.empty()) {
168	    return 1;
169	  }
170	  if (non_list_lens.size() > 1) {
171	    GELOGE(ge::PARAM_INVALID, "Element num of DataType and Format is not aligned.");
172	    return 0;
173	  }
174	  if (*non_list_lens.begin() == 0) {
175	    GELOGE(ge::PARAM_INVALID, "DataType or Format cannot be empty.");
176	    return 0;
177	  }
178	  return *non_list_lens.begin();
179	}
