205	void OpDefImpl::UpdateDtypeImpl(const OpDef::DfsParam &dfs_param, OpParamDef &param, const uint32_t &param_idx) {
206	  uint32_t param_type = dfs_param.full_types[0][param_idx].first;
207	  bool have_scalar_param = !(dfs_param.full_types[0][param_idx].second);
208	  if (have_scalar_param && static_cast<ge::DataType>(param_type) != ge::DT_UNDEFINED) {
209	    if (param.IsSetDtypeForBin()) {
210	      GELOGW("DataTypeForBinQuery is incompatible with To Type.");
211	      param.impl_->set_type_for_bin = false;
212	    }
213	    param.impl_->types = std::vector<ge::DataType>(dfs_param.full_types.size(), static_cast<ge::DataType>(param_type));
214	    return;
215	  }
216	  if (have_scalar_param && static_cast<ge::DataType>(param_type) == ge::DT_UNDEFINED) {
217	    return;
218	  }
219	  uint32_t num = 0;
220	  bool is_idx = false;
221	  std::vector<ge::DataType> data_types;
222	  std::vector<ge::DataType> data_types_for_bin;
223	  bool is_follow_list =
224	      (param.impl_->follow_type == FollowType::ALL || param.impl_->follow_type == FollowType::DTYPE) &&
225	      param.IsDtypeList();
226	  for (uint32_t type_idx = 0; type_idx < dfs_param.full_types.size(); ++type_idx) {
227	    std::tie(num, is_idx) = dfs_param.full_types[type_idx][param_idx];
228	    if (param.IsSetDtypeForBin() && is_idx && !is_follow_list) {
229	      data_types_for_bin.emplace_back(param.impl_->types_for_bin[num]);
230	    }
231	    if (param.IsDtype()) {
232	      data_types.emplace_back(param.impl_->types[num]);
233	    }
234	    if (param.IsDtypeList()) {
235	      data_types.emplace_back(param.impl_->types_list[num]);
236	    }
237	  }
238	  if (!data_types_for_bin.empty()) {
239	    param.impl_->types_for_bin = data_types_for_bin;
240	  }
241	  param.impl_->types = data_types;
242	  return;
243	}
