254	        std::vector<ge::Format>(dfs_param.full_formats.size(), static_cast<ge::Format>(param_format));
255	    return;
256	  }
257	  uint32_t num = 0;
258	  bool is_idx = false;
259	  std::vector<ge::Format> data_formats;
260	  std::vector<ge::Format> data_formats_for_bin;

