    return *parent_this;
  }
  if (section == CommentSection::CATEGORY) {
    if (strchr(comment, ' ') != nullptr) {
      GELOGE(ge::PARAM_INVALID, "Ops %s : category names cannot be split by spaces",
             parent_this->GetOpType().GetString());
      return *parent_this;
